PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?deathDate WHERE {
  VALUES ?film { dbr:Love_That_Brute dbr:Laughing_Heirs }

  # director (prefer dbp:director, fallback to dbo:director)
  OPTIONAL { ?film dbp:director ?director . }
  OPTIONAL { ?film dbo:director ?director . }
  FILTER (BOUND(?director))

  # death date of the director (prefer dbp:deathDate, fallback to dbo:deathDate)
  OPTIONAL { ?director dbp:deathDate ?dbpDeath . }
  OPTIONAL { ?director dbo:deathDate ?dboDeath . }
  BIND (COALESCE(?dbpDeath, ?dboDeath) AS ?deathDate)
}
LIMIT 100

